/* ============================================================
   portal-nav.js — NAVEGACAO UNIVERSAL DO PORTAL
   Alfacem Global Academy · versao Cloudflare Pages

   UM arquivo, TODAS as telas. Antes o menu era copiado dentro de
   cada HTML (havia 5 versoes diferentes do mesmo menu em 7 arquivos,
   mais uma sidebar propria nos 5 dashboards). Agora existe so este.

   O que ele faz:
     1. rotaTela()  — resolve o destino dos links (nomes de arquivo)
     2. injeta o CSS e o HTML do menu lateral em qualquer tela
     3. marca sozinho o item ATIVO, olhando o nome do arquivo
     4. aplica os gates de cargo (quem nao pode, nao ve e nao navega)
     5. roteia todo clique em [data-portal]
     6. nos dashboards, monta tambem o grupo "Secoes" a partir da
        .sidebar da propria pagina (rolagem + destaque do que esta na tela)

   Para mudar o menu, mexa SO AQUI.
   ============================================================ */

/* ===== 1. rotaTela() — no Pages tudo e arquivo estatico, mesma origem ===== */
window.rotaTela = function(dest){
  if(dest == null) return dest;
  return String(dest);
};

function montarNavegacao(){
  "use strict";
  if(document.getElementById('vnav-styles') || document.getElementById('vnav')) return;

  /* ===== 2. CSS ===== */
  var css = `
:root{ --mandala: url('data:image/png;base64,');  --vnav-bg-1:#2a1d5e; --vnav-bg-2:#1a1238; --vnav-acc:#8a6aff; --vnav-acc-2:#d65aa0; --vnav-ink:#cfc8ee; --vnav-dim:#8c84b8; }
/* === paleta dos dashboards padronizada com a barra (rosa -> roxo) === */
:root{ --brand:#8a6aff; --brand-soft:#EEE9FF; --nav:#2a1d5e; --nav-2:#1a1238; }
.hero{ background:linear-gradient(125deg,#2a1d5e 0%,#1a1238 55%,#3a2a72 100%) !important; }
.avatar{ background:linear-gradient(135deg,#8a6aff,#d65aa0) !important; box-shadow:0 8px 22px rgba(138,106,255,.4) !important; }
.sec-num{ background:linear-gradient(135deg,#8a6aff,#6d4ad6) !important; box-shadow:0 2px 8px rgba(138,106,255,.3) !important; }
.pct-fill{ background:linear-gradient(90deg,#8a6aff,#d65aa0) !important; }
.brand-mark{ background:linear-gradient(135deg,#8a6aff,#d65aa0) !important; box-shadow:0 6px 16px rgba(138,106,255,.4) !important; }
.gd-tag{ color:#b9a7ff !important; }
.btn-brand,.rf-reset{ background:#D6306E !important; }
body{ padding-left:22px; }
/* fixar o menu = mantê-lo aberto POR CIMA (overlay), sem empurrar/mover a página */
body.nav-pinned{ padding-left:22px; }
.app > .sidebar{ display:none !important; }          /* esconde a barra escura antiga */
.vnav{ position:fixed;left:0;top:0;bottom:0;width:22px;z-index:50;
  background:linear-gradient(180deg,var(--vnav-bg-1),var(--vnav-bg-2));
  color:var(--vnav-ink);display:flex;flex-direction:column;padding:18px 12px;overflow:hidden;
  box-shadow:6px 0 28px rgba(20,12,55,.22);border-right:1px solid rgba(255,255,255,.06);
  transition:width .28s cubic-bezier(.4,0,.2,1),box-shadow .28s ease;font-family:'Inter',system-ui,sans-serif; }
.vnav:hover,.vnav:focus-within{width:240px;overflow-y:auto;box-shadow:14px 0 46px rgba(20,12,55,.45)}
.vnav>*{opacity:0;transition:opacity .16s ease}
.vnav:hover>*,.vnav:focus-within>*{opacity:1;transition:opacity .22s ease .06s}
body.nav-pinned .vnav{width:240px;overflow-y:auto;box-shadow:6px 0 28px rgba(20,12,55,.22)}
body.nav-pinned .vnav>*{opacity:1}
.vnav-brand,.vnav-brand-txt,.vnav-brand-sub,.vnav-head,.vnav-top,.vnav-item,.vnav-label,.vnav-foot{white-space:nowrap}
.vnav::before{ content:"\\2630";position:absolute;top:18px;left:50%;transform:translateX(-50%);font-size:13px;line-height:1;color:#fff;opacity:.92;transition:opacity .16s ease;pointer-events:none;z-index:1; }
.vnav::after{ content:"MENU";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);writing-mode:vertical-rl;text-orientation:upright;font-size:9px;font-weight:800;letter-spacing:2px;color:var(--vnav-acc);opacity:.9;transition:opacity .16s ease;pointer-events:none;z-index:1; }
.vnav:hover::before,.vnav:hover::after,.vnav:focus-within::before,.vnav:focus-within::after,body.nav-pinned .vnav::before,body.nav-pinned .vnav::after{opacity:0}
/* mandala do rodape da barra FECHADA (::before e ::after ja estao ocupados
   pelo ☰ e pelo "MENU" na vertical, por isso ela e um elemento de verdade).
   Recolorida por mascara, como a .vnav-logo: o PNG e so a forma, a cor vem
   daqui — assim ela acompanha o roxo do menu (--vnav-acc).
   A regra .vnav>*{opacity:0} apaga todo filho enquanto a barra esta fechada,
   que e o oposto do que se quer aqui; as duas regras abaixo invertem isso
   com especificidade maior: aparece fechada, some quando o menu abre. */
.vnav>.vnav-mandala{ position:absolute;bottom:16px;left:50%;transform:translateX(-50%);
  width:15px;height:15px;background:var(--vnav-acc);
  -webkit-mask:var(--mandala) center/contain no-repeat;mask:var(--mandala) center/contain no-repeat;
  opacity:.92;transition:opacity .16s ease;pointer-events:none;z-index:1; }
.vnav:hover>.vnav-mandala,.vnav:focus-within>.vnav-mandala,body.nav-pinned .vnav>.vnav-mandala{opacity:0}
.vnav-pin{ position:absolute;top:14px;right:9px;z-index:2;width:30px;height:30px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.16);border-radius:9px;background:rgba(255,255,255,.06);color:var(--vnav-ink);cursor:pointer;transition:background .15s,color .15s,border-color .15s; }
.vnav-pin:hover{background:rgba(255,255,255,.14);color:#fff}
.vnav-pin svg{transition:transform .2s ease}
body.nav-pinned .vnav-pin{background:linear-gradient(135deg,var(--vnav-acc),var(--vnav-acc-2));border-color:transparent;color:#fff}
body.nav-pinned .vnav-pin svg{transform:rotate(-35deg)}
.vnav::-webkit-scrollbar{width:6px}
.vnav::-webkit-scrollbar-thumb{background:rgba(255,255,255,.14);border-radius:3px}
.vnav-brand{display:flex;align-items:center;gap:11px;padding:2px 8px 16px;margin-bottom:8px;border-bottom:1px solid rgba(255,255,255,.08)}
.vnav-logo{width:34px;height:34px;flex:none;background:linear-gradient(135deg,var(--vnav-acc),var(--vnav-acc-2));-webkit-mask:var(--mandala) center/contain no-repeat;mask:var(--mandala) center/contain no-repeat}
.vnav-brand-txt{font-weight:800;color:#fff;font-size:13px;line-height:1.15;display:block}
.vnav-brand-sub{font-size:9.5px;color:var(--vnav-dim);letter-spacing:.07em;text-transform:uppercase;margin-top:2px;display:block}
.vnav-label{font-size:9.5px;letter-spacing:.13em;text-transform:uppercase;color:var(--vnav-dim);padding:14px 12px 4px;font-weight:700}
.vnav-group{display:flex;flex-direction:column}
.vnav-head{display:flex;align-items:center;gap:9px;padding:9px 12px;border-radius:10px;color:#fff;font-size:13px;font-weight:700;cursor:pointer;transition:.15s;-webkit-user-select:none;user-select:none}
.vnav-head:hover{background:rgba(255,255,255,.06)}
.vnav-top{display:flex;align-items:center;gap:9px;padding:9px 12px;border-radius:10px;color:#fff;font-size:13px;font-weight:700;cursor:pointer;transition:.15s;text-decoration:none;position:relative}
.vnav-top:hover{background:rgba(255,255,255,.06)}
.vnav-top.active{background:linear-gradient(90deg,rgba(138,106,255,.30),rgba(214,90,160,.05))}
.vnav-top.active::after{content:"";position:absolute;left:0;top:8px;bottom:8px;width:3px;border-radius:3px;background:linear-gradient(180deg,var(--vnav-acc),var(--vnav-acc-2))}
.vnav-ico{width:18px;height:18px;flex:none;opacity:.9;display:grid;place-items:center}
.vnav-chev{margin-left:auto;width:14px;height:14px;flex:none;transition:transform .25s;opacity:.8}
.vnav-sub{display:flex;flex-direction:column;gap:1px;max-height:0;overflow:hidden;transition:max-height .3s ease;padding-left:6px}
.vnav-group:hover .vnav-sub,.vnav-group.open .vnav-sub{max-height:760px}
.vnav-group:hover .vnav-chev,.vnav-group.open .vnav-chev{transform:rotate(90deg)}
.vnav-item{display:flex;align-items:center;gap:9px;padding:7px 12px 7px 16px;border-radius:9px;color:var(--vnav-ink);text-decoration:none;font-size:12.5px;font-weight:500;cursor:pointer;transition:.15s;position:relative}
.vnav-item::before{content:"";width:5px;height:5px;border-radius:50%;background:rgba(255,255,255,.28);flex:none;transition:.15s}
.vnav-item:hover{background:rgba(255,255,255,.06);color:#fff}
.vnav-item:hover::before{background:var(--vnav-acc)}
.vnav-item.active{background:linear-gradient(90deg,rgba(138,106,255,.30),rgba(214,90,160,.05));color:#fff}
.vnav-item.active::after{content:"";position:absolute;left:0;top:6px;bottom:6px;width:3px;border-radius:3px;background:linear-gradient(180deg,var(--vnav-acc),var(--vnav-acc-2))}
.vnav-foot{margin-top:auto;padding:12px 12px 4px;font-size:9.5px;color:var(--vnav-dim);border-top:1px solid rgba(255,255,255,.08)}
/* a marca e um PNG usado como MASCARA: assim ela pega a cor do menu (clara
   sobre o roxo escuro) em vez de vir com o preto do arquivo original */
.vnav-dev{display:inline-flex;align-items:center;gap:3px;opacity:.75;transition:opacity .2s}
.vnav-dev:hover{opacity:1}
.vnav-dev-logo{display:inline-block;width:46px;height:16px;margin-left:-2px;background-color:currentColor;
  -webkit-mask:url('assets/logo-dev.png') center/contain no-repeat;
          mask:url('assets/logo-dev.png') center/contain no-repeat}
@media(max-width:860px){ .vnav{display:none} body,body.nav-pinned{padding-left:0} }`;
  var st = document.createElement('style'); st.id = 'vnav-styles'; st.textContent = css;
  document.head.appendChild(st);

  /* ===== 3. cargos da sessao (mesma regra do index: principal + acessos[]) =====
     O backend as vezes grava o cargo como ROTULO ("Supervisao de Bilinguismo")
     em vez do codigo. Por isso tudo passa por resolverCargo() antes de comparar. */
  var CARGO_LABELS = {
    ADMIN:'Administracao', PROFESSOR:'Professor',
    SUPERVISAO_SEGMENTO:'Supervisão de Segmento',
    SUPERVISAO_BILINGUISMO:'Supervisao de Bilinguismo',
    COORDENACAO_AREA:'Coordenação de Área',
    DIRECAO_UNIDADE:'Direção de Unidade',
    DIRECAO_PEDAGOGICA:'Direção Pedagógica',
    DIRECAO_PEDAGOGICA_GERAL:'Direcao Pedagogica Geral',
    DIRECAO_GERAL:'Direcao Geral'
  };
  function canonizar(v){
    return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
      .trim().toUpperCase().replace(/[\s\-]+/g,'_').replace(/_+/g,'_');
  }
  function resolverCargo(v){
    var alvo = canonizar(v); if(!alvo) return '';
    for(var code in CARGO_LABELS){
      if(alvo === canonizar(code) || alvo === canonizar(CARGO_LABELS[code])) return code;
    }
    return alvo;
  }
  function sessao(chave){ try{ return JSON.parse(sessionStorage.getItem(chave) || '{}'); }catch(e){ return {}; } }
  function cargosDaSessao(){
    var perm = sessao('permissoes'), user = sessao('usuario_logado');
    var out = [perm.cargo_principal, user.perfil, user.cargo_codigo];
    if(Array.isArray(perm.acessos)) perm.acessos.forEach(function(a){ out.push(a && a.cargo_codigo); });
    if(perm.admin_global === true) out.push('ADMIN');
    return out.filter(Boolean).map(resolverCargo);
  }
  function emailDaSessao(){
    var user = sessao('usuario_logado');
    return String(user.email || '').trim().toLowerCase();
  }
  /* topo da rede: ve tudo, em modo leitura */
  function ehVisualizadorGeral(){
    var c = cargosDaSessao();
    return c.indexOf('DIRECAO_GERAL') >= 0 || c.indexOf('DIRECAO_PEDAGOGICA_GERAL') >= 0
        || emailDaSessao() === 'usuario1@exemplo.edu.br';
  }
  /* CASCATA: gestor abre em SO LEITURA a tela que os liderados dele avaliam.
     Espelha o CASCATA_VISUALIZACAO do index.html e o SQL listar-docentes. */
  var CASCATA = { 'form-docente': ['DIRECAO_UNIDADE','DIRECAO_PEDAGOGICA'] };
  function podeAbrir(item){
    var c = cargosDaSessao();
    if(!c.length) return true;                                 /* sem sessao lida: nao esconde nada */
    if(c.indexOf('ADMIN') >= 0) return true;
    if(!item.cargos || !item.cargos.length) return true;       /* item sem gate: livre */
    if(item.cargos.some(function(x){ return c.indexOf(x) >= 0; })) return true;
    if(item.leitura && ehVisualizadorGeral()) return true;      /* topo entra p/ visualizar */
    var casc = CASCATA[item.portal];                            /* cascata p/ baixo */
    if(casc && casc.some(function(x){ return c.indexOf(x) >= 0; })) return true;
    return false;
  }

  /* ===== 4. O MENU (fonte unica) =====
     portal  : chave usada no roteamento e no estado ativo
     arquivo : destino
     cargos  : quem avalia nessa tela (vazio = todos)
     leitura : topo da rede tambem entra, em modo leitura */
  var MENU = {
    inicio:      { portal:'inicio',          arquivo:'index.html',                 titulo:'Início' },
    dashGeral:   { portal:'dash-completo',   arquivo:'dashboard_geral.html',    titulo:'Dashboard Geral - Gestor' },
    dashIndiv:   { portal:'dash-individual', arquivo:null,                         titulo:'Dashboard Individual - Liderado' },
    formDocente: { portal:'form-docente',    arquivo:'FORMULARIO.html',            titulo:'Docentes',
                   cargos:['COORDENACAO_AREA','SUPERVISAO_SEGMENTO','SUPERVISAO_BILINGUISMO'], leitura:true },
    formSup:     { portal:'form-supervisao', arquivo:'formulario_supervisao.html', titulo:'Supervisão',
                   cargos:['DIRECAO_UNIDADE','DIRECAO_PEDAGOGICA'], leitura:true },
    formDU:      { portal:'form-du',         arquivo:'formulario_direcao_unidade.html',         titulo:'Direção de Unidade',
                   cargos:['DIRECAO_PEDAGOGICA','DIRECAO_PEDAGOGICA_GERAL'], leitura:true },
    formDP:      { portal:'form-dp',         arquivo:'formulario_direcao_pedagogica.html',         titulo:'Diretor Pedagógico',
                   cargos:['DIRECAO_PEDAGOGICA_GERAL'], leitura:true },
    ferias:      { portal:'ferias',          arquivo:'ferias.html',                titulo:'Controle de Férias' },
    gestao:      { portal:'gestao-pessoas',  arquivo:'gestao-pessoas.html',        titulo:'Gestão de Pessoas',
                   cargos:['ADMIN','DIRECAO_GERAL','DIRECAO_PEDAGOGICA_GERAL'] },
    chamados:    { portal:'chamados',        arquivo:'painel_suporte.html',        titulo:'Chamados de Suporte',
                   cargos:['ADMIN','DIRECAO_GERAL','DIRECAO_PEDAGOGICA_GERAL'] },
    dashComp:    { portal:'dash-comparativo', arquivo:'dashboard_comparativo.html', titulo:'Comparativo por Cargo',
                   /* DP entra só no próprio segmento (a tela recorta) — 29/10/2026 */
                   cargos:['ADMIN','DIRECAO_GERAL','DIRECAO_PEDAGOGICA_GERAL','DIRECAO_PEDAGOGICA'] },
    /* sem `cargos`: o histórico de atualizacoes e a descricao da plataforma
       sao para todo mundo — quem usa o portal tem o direito de saber o que
       mudou nele sem depender de alguem avisar */
    atualiz:     { portal:'atualizacoes',    arquivo:'atualizacoes.html',          titulo:'Atualizações' }
  };

  /* arquivo atual -> chave do portal (para marcar o item ativo sozinho) */
  var ATIVO_POR_ARQUIVO = {
    'index.html':'inicio',
    'dashboard_geral.html':'dash-completo',
    'dashboard_docente_individual.html':'dash-individual',
    'dashboard_supervisao_individual.html':'dash-individual',
    'dashboard_direcao_unidade_individual.html':'dash-individual',
    'dashboard_direcao_pedagogica_individual.html':'dash-individual',
    'FORMULARIO.html':'form-docente',
    'formulario_supervisao.html':'form-supervisao',
    'formulario_direcao_unidade.html':'form-du',
    'formulario_direcao_pedagogica.html':'form-dp',
    'ferias.html':'ferias',
    'gestao-pessoas.html':'gestao-pessoas',
    'painel_suporte.html':'chamados',
    'atualizacoes.html':'atualizacoes',
    'dashboard_comparativo.html':'dash-comparativo'
  };
  function arquivoAtual(){
    var p = String(location.pathname || '').split('/').pop();
    return p || 'index.html';
  }
  var PORTAL_ATIVO = ATIVO_POR_ARQUIVO[arquivoAtual()] || '';

  /* ===== 5. icones ===== */
  var CHEV       = '<svg class="vnav-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M9 18l6-6-6-6"/></svg>';
  var ICO_DASH   = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="9"/><rect x="14" y="3" width="7" height="5"/><rect x="14" y="12" width="7" height="9"/><rect x="3" y="16" width="7" height="5"/></svg>';
  var ICO_AVAL   = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>';
  var ICO_SEC    = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>';
  var ICO_PIN    = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="17" x2="12" y2="22"/><path d="M5 17h14l-1.6-3.2a2 2 0 0 1-.4-1.2V6a2 2 0 0 0-2-2H9a2 2 0 0 0-2 2v6.6a2 2 0 0 1-.4 1.2L5 17z"/></svg>';
  var ICO_HOME   = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9.5L12 3l9 6.5"/><path d="M5 10v10a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V10"/><path d="M9 21v-6h6v6"/></svg>';
  var ICO_FERIAS = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>';
  var ICO_GP     = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>';

  function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  function ativoDe(item){ return item.portal === PORTAL_ATIVO ? ' active' : ''; }
  function atrAtivo(item){ return item.portal === PORTAL_ATIVO ? ' aria-current="page"' : ''; }

  var ICO_SUP    = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3.6"/><path d="M5.6 5.6l3.9 3.9M14.5 14.5l3.9 3.9M18.4 5.6l-3.9 3.9M9.5 14.5l-3.9 3.9"/></svg>';
  var ICO_ATUALIZ= '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v5h5"/><path d="M20 12a8 8 0 1 1-2.3-5.6L20 8.5"/><path d="M12 8.5V12l2.5 1.6"/></svg>';
  function topo(item, ico){
    return '<a class="vnav-top' + ativoDe(item) + '" data-portal="' + esc(item.portal) + '"'
      + ' role="button" tabindex="0" aria-label="' + esc(item.titulo) + '"' + atrAtivo(item) + '>'
      + '<span class="vnav-ico">' + ico + '</span>' + esc(item.titulo) + '</a>';
  }
  function subItem(item){
    return '<a class="vnav-item' + ativoDe(item) + '" data-portal="' + esc(item.portal) + '"'
      + ' role="button" tabindex="0"' + atrAtivo(item) + '>' + esc(item.titulo) + '</a>';
  }
  function grupo(id, ico, titulo, itensHTML, aberto){
    return '<div class="vnav-group' + (aberto ? ' open' : '') + '" data-grp="' + id + '">'
      + '<div class="vnav-head" role="button" tabindex="0" aria-label="' + esc(titulo) + '">'
      + '<span class="vnav-ico">' + ico + '</span>' + esc(titulo) + CHEV + '</div>'
      + '<div class="vnav-sub">' + itensHTML + '</div></div>';
  }

  /* ===== 6. "Secoes" — so existe nos dashboards, lido da .sidebar da propria tela ===== */
  var secoes = [];
  Array.prototype.forEach.call(document.querySelectorAll('.sidebar .nav-item[data-sec]'), function(n){
    var clone = n.cloneNode(true);
    Array.prototype.forEach.call(clone.querySelectorAll('.num,.star'), function(x){ x.remove(); });
    var label = (clone.textContent || '').trim();
    if(n.dataset.sec && label) secoes.push({ sec:n.dataset.sec, label:label });
  });
  var secItens = secoes.map(function(s){
    return '<a class="vnav-item" data-sec="' + esc(s.sec) + '">' + esc(s.label) + '</a>';
  }).join('');

  /* ===== 7. monta e insere ===== */
  var grupoDashAberto = (PORTAL_ATIVO === 'dash-completo' || PORTAL_ATIVO === 'dash-individual'
                       || PORTAL_ATIVO === 'dash-comparativo');
  var grupoAvalAberto = ['form-docente','form-supervisao','form-du','form-dp'].indexOf(PORTAL_ATIVO) >= 0;

  var aside = document.createElement('aside');
  aside.className = 'vnav'; aside.id = 'vnav';
  aside.setAttribute('aria-label','Navegação principal');
  aside.innerHTML =
      '<button type="button" class="vnav-pin" id="vnavPin" aria-pressed="false" aria-label="Fixar menu aberto" title="Fixar menu">' + ICO_PIN + '</button>'
    + '<span class="vnav-mandala" aria-hidden="true"></span>'
    + '<div class="vnav-brand"><span class="vnav-logo" role="img" aria-label="Alfacem"></span>'
    + '<span><span class="vnav-brand-txt">Painel de gestores</span>'
    + '<span class="vnav-brand-sub">Rede Alfacem Global Academy</span></span></div>'
    + '<div class="vnav-label">Menu</div>'
    + topo(MENU.inicio, ICO_HOME)
    + grupo('dashboard', ICO_DASH, 'Dashboard', subItem(MENU.dashGeral) + subItem(MENU.dashIndiv) + subItem(MENU.dashComp), grupoDashAberto)
    + grupo('avaliacoes', ICO_AVAL, 'Avaliações',
        subItem(MENU.formDocente) + subItem(MENU.formSup) + subItem(MENU.formDU) + subItem(MENU.formDP), grupoAvalAberto)
    + topo(MENU.ferias, ICO_FERIAS)
    + topo(MENU.gestao, ICO_GP)
    + topo(MENU.chamados, ICO_SUP)
    /* Suporte: nao navega, abre o modal de chamado (ver modulo no fim do arquivo) */
    + '<a class="vnav-top" data-portal="suporte" role="button" tabindex="0" aria-label="Suporte">'
    +   '<span class="vnav-ico">' + ICO_SUP + '</span>Suporte</a>'
    /* >>> SECOES POR ULTIMO. <<< E o unico grupo de tamanho variavel: nos
       dashboards ele tem 15+ itens e, no meio da lista, empurrava Suporte
       para fora da primeira tela. No fim, a navegacao do portal fica toda
       visivel e o indice da propria pagina vem depois dela. */
    + topo(MENU.atualiz, ICO_ATUALIZ)
    + (secItens ? grupo('secoes', ICO_SEC, 'Seções', secItens, true) : '')
    /* a assinatura do rodape: era repetida dentro dos 5 formularios e some
       deles — aqui ela aparece uma vez so, em toda tela que tem o menu */
    + '<div class="vnav-foot"><span class="vnav-dev">Designed &amp; developed by'
    +   '<span class="vnav-dev-logo" role="img" aria-label="Assinatura do desenvolvedor"></span></span></div>';
  /* >>> ONDE MONTAR: dentro do #app quando ele existir. <<<
     O index.html é login E portal no mesmo arquivo, e o showScreen() alterna
     os dois contêineres:  $('auth').classList.toggle('hidden', !ehLogin)
                           $('app').classList.toggle('hidden',  ehLogin)
     No original o <aside class="vnav"> ficava DENTRO do #app e herdava esse
     esconde/mostra de graça. Montando no <body> o menu escapa da troca e
     aparece na TELA DE LOGIN, antes de haver sessão (visto em produção,
     25/09/2026). O ferias.html usa o mesmo padrão: revela o #app só depois
     de validar a sessão e o esconde de novo quando bloqueia.
     As demais telas não têm #app — nelas segue no body, como antes. */
  var hospedeiro = document.getElementById('app') || document.body;
  hospedeiro.insertBefore(aside, hospedeiro.firstChild);

  /* ===== 8. gates: quem nao tem cargo some do menu ===== */
  var PORTAL_ITEM = {};
  Object.keys(MENU).forEach(function(k){ PORTAL_ITEM[MENU[k].portal] = MENU[k]; });
  function aplicarGates(){
    Array.prototype.forEach.call(aside.querySelectorAll('[data-portal]'), function(el){
      var item = PORTAL_ITEM[el.dataset.portal];
      if(!item) return;
      el.style.display = podeAbrir(item) ? '' : 'none';
    });
    /* grupo sem nenhum filho visivel tambem some */
    Array.prototype.forEach.call(aside.querySelectorAll('.vnav-group[data-grp]'), function(g){
      if(g.dataset.grp === 'secoes') return;
      var vivos = Array.prototype.filter.call(g.querySelectorAll('.vnav-item'), function(i){ return i.style.display !== 'none'; });
      g.style.display = vivos.length ? '' : 'none';
    });
  }
  aplicarGates();

  /* ===== 9. roteamento ===== */
  function irPara(arquivo){
    try{ sessionStorage.setItem('portal_return_screen', 'options'); }catch(e){}
    window.location.href = window.rotaTela(arquivo);
  }
  document.addEventListener('click', function(e){
    var el = e.target && e.target.closest ? e.target.closest('[data-portal]') : null;
    if(!el) return;
    e.preventDefault();
    var chave = el.dataset.portal;
    var item  = PORTAL_ITEM[chave];

    if(chave === 'inicio'){
      try{ sessionStorage.removeItem('portal_return_screen'); }catch(_){}
      window.location.href = window.rotaTela('index.html'); return;
    }
    if(chave === 'suporte'){
      if(typeof window.abrirSuporte === 'function') window.abrirSuporte();
      return;
    }
    if(chave === 'dash-individual'){
      if(typeof window.abrirSeletorIndividual === 'function'){ window.abrirSeletorIndividual(); return; }
      if(typeof window.openIndividualList === 'function'){ window.openIndividualList(); return; }
      irPara('dashboard_geral.html'); return;
    }
    if(item && item.arquivo){
      if(!podeAbrir(item)) return;   /* trava mesmo se o item vazou p/ a tela */
      irPara(item.arquivo);
    }
  });
  /* teclado: Enter/Espaco nos itens */
  aside.addEventListener('keydown', function(e){
    if(e.key !== 'Enter' && e.key !== ' ') return;
    var el = e.target && e.target.closest ? e.target.closest('[data-portal],[data-sec],.vnav-head') : null;
    if(!el) return;
    e.preventDefault(); el.click();
  });

  /* ===== 10. acordeoes ===== */
  Array.prototype.forEach.call(aside.querySelectorAll('.vnav-head'), function(head){
    head.addEventListener('click', function(){
      var g = head.closest('.vnav-group'); if(g) g.classList.toggle('open');
    });
  });

  /* ===== 11. secoes: rolar ate a ancora (dashboards) ===== */
  Array.prototype.forEach.call(aside.querySelectorAll('.vnav-item[data-sec]'), function(it){
    it.addEventListener('click', function(){
      var side = document.querySelector('.sidebar .nav-item[data-sec="' + it.dataset.sec + '"]');
      if(side){ side.click(); return; }                        /* deixa o dashboard fazer o trabalho dele */
      var alvo = document.getElementById(it.dataset.sec);
      if(alvo && alvo.scrollIntoView) alvo.scrollIntoView({ behavior:'smooth', block:'start' });
    });
  });

  /* ===== 12. pin (fixar aberto) ===== */
  var pin = aside.querySelector('#vnavPin');
  if(pin){
    var aplicarPin = function(fixo){
      document.body.classList.toggle('nav-pinned', fixo);
      var app = document.getElementById('app');
      if(app) app.classList.toggle('nav-pinned', fixo);
      pin.setAttribute('aria-pressed', fixo ? 'true' : 'false');
      pin.title = fixo ? 'Desafixar menu' : 'Fixar menu';
      try{ localStorage.setItem('vnav_fixo', fixo ? '1' : '0'); }catch(e){}
    };
    pin.addEventListener('click', function(e){
      e.stopPropagation();
      aplicarPin(!document.body.classList.contains('nav-pinned'));
    });
    var salvo = '0'; try{ salvo = localStorage.getItem('vnav_fixo') || '0'; }catch(e){}
    if(salvo === '1') aplicarPin(true);
  }

  /* ===== 13. destaque da secao visivel (dashboards) ===== */
  if(secoes.length && 'IntersectionObserver' in window){
    var mapa = {};
    Array.prototype.forEach.call(aside.querySelectorAll('.vnav-item[data-sec]'), function(i){ mapa[i.dataset.sec] = i; });
    var obs = new IntersectionObserver(function(entradas){
      entradas.forEach(function(en){
        if(!en.isIntersecting) return;
        var id = en.target.id || en.target.getAttribute('data-sec');
        Array.prototype.forEach.call(aside.querySelectorAll('.vnav-item[data-sec]'), function(i){ i.classList.remove('active'); });
        if(mapa[id]) mapa[id].classList.add('active');
      });
    }, { rootMargin:'-45% 0px -50% 0px' });
    secoes.forEach(function(s){ var el = document.getElementById(s.sec); if(el) obs.observe(el); });
  }
}

/* ===== 14. quando montar =====
   rotaTela() ja foi definida la em cima (sincrono, antes de qualquer
   script inline da pagina chamar). O menu so e montado quando o <body>
   existe — assim este arquivo pode ser carregado no <head>. */
if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', montarNavegacao);
else montarNavegacao();


/* ============================================================
   SUPORTE — item do menu lateral que abre um chamado
   ------------------------------------------------------------
   v1 cobre um motivo: a lista de quem a pessoa avalia está errada.
     "Estou vendo alguém que não deveria"  -> marca quem sobra na lista dela
     "Não vejo alguém que deveria"         -> descreve quem falta

   POR QUE MORA AQUI, e não numa tela nova:
   este arquivo já é carregado pelas 14 telas. Um suporte.html exigiria
   navegação (perder o que a pessoa está fazendo), entraria na lista do
   gerador e no menu — e o problema que ela quer relatar quase sempre é
   sobre a tela em que ela está. Modal resolve sem tirar ninguém do lugar.

   DE ONDE SAI A LISTA "quem eu avalio":
   dos MESMOS endpoints que os formulários usam, todos chamados de uma vez;
   o que a pessoa não pode ver volta vazio. Não há regra de cargo duplicada
   aqui de propósito — cada listar já sabe responder "quem esta pessoa
   avalia", e uma segunda cópia dessa regra divergiria da primeira.
   ============================================================ */
(function(){
  "use strict";

  var API = '/webhook';   /* mesma origem: functions/webhook/[[path]].js leva ao n8n */

  /* os cinco instrumentos. Quem não avalia aquele grupo recebe lista vazia. */
  var LISTAS = [
    { rota:'/acompanhamento-docente/listar-docentes',             grupo:'Docentes',
      corpo:{ tipo_codigo:'ACOMPANHAMENTO_DOCENTE', filtros:{} } },
    { rota:'/acompanhamento-supervisao/listar-supervisores',      grupo:'Supervisão', corpo:{} },
    { rota:'/acompanhamento-direcao/listar-unidades',             grupo:'Direção de Unidade', corpo:{} },
    { rota:'/acompanhamento-direcao-pedagogica/listar-diretores', grupo:'Direção Pedagógica', corpo:{} },
    { rota:'/acompanhamento-coordenacao/listar-coordenadores',    grupo:'Coordenação de Área', corpo:{} }
  ];

  var CARGOS = [
    { v:'DOCENTE',              t:'Professor(a)' },
    { v:'SUPERVISAO_SEGMENTO',  t:'Supervisão de Segmento' },
    { v:'COORDENACAO_AREA',     t:'Coordenação de Área' },
    { v:'DIRECAO_UNIDADE',      t:'Direção de Unidade' },
    { v:'DIRECAO_PEDAGOGICA',   t:'Direção Pedagógica' },
    { v:'OUTRO',                t:'Outro / não sei' }
  ];
  var SEGMENTOS = ['EI','EFAI','EFAF','EM'];

  function tok(){ try{ return sessionStorage.getItem('session_token') || ''; }catch(e){ return ''; } }
  function esc(v){ return String(v==null?'':v).replace(/[&<>"']/g, function(c){
    return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]; }); }

  function post(rota, corpo){
    var t = tok();
    return fetch(API + rota, {
      method:'POST',
      headers:{ 'Content-Type':'application/json', 'Authorization':'Bearer ' + t },
      body: JSON.stringify(Object.assign({}, corpo || {}, { token: t }))
    }).then(function(r){ return r.text(); }).then(function(txt){
      if(!txt) return {};
      try{ return JSON.parse(txt); }catch(e){ return {}; }
    });
  }

  /* As respostas não têm formato único: umas devolvem array direto, outras um
     objeto com a lista dentro, e o n8n às vezes embrulha tudo em [ {...} ].
     Em vez de assumir, procura a primeira lista plausível. */
  function extrairLista(resp){
    if(Array.isArray(resp)){
      if(resp.length === 1 && resp[0] && typeof resp[0] === 'object' && !ehPessoa(resp[0])) return extrairLista(resp[0]);
      return resp;
    }
    if(!resp || typeof resp !== 'object') return [];
    var chaves = ['avaliados','supervisores','diretores','coordenadores','unidades','docentes','lista','itens'];
    for(var i=0;i<chaves.length;i++) if(Array.isArray(resp[chaves[i]])) return resp[chaves[i]];
    return [];
  }
  function ehPessoa(o){
    return !!(o.professor_nome || o.supervisor_nome || o.diretor_nome || o.nome || o.avaliado_nome);
  }
  /* cada instrumento nomeia os campos do seu jeito; aqui vira um formato só */
  function normalizar(o, grupo){
    var nome = o.professor_nome || o.supervisor_nome || o.diretor_nome || o.avaliado_nome || o.nome || '';
    var id   = o.professor_id || o.supervisor_id || o.diretor_id || o.avaliado_usuario_id || o.usuario_id || o.id || null;
    var det  = [];
    if(o.disciplina_nome) det.push(o.disciplina_nome);
    if(o.area_nome) det.push(o.area_nome);
    if(o.unidade_nome) det.push(o.unidade_nome);
    if(Array.isArray(o.segmentos) && o.segmentos.length) det.push(o.segmentos.join('+'));
    else if(o.segmento_codigo) det.push(o.segmento_codigo);
    var mail = o.supervisor_email || o.professor_email || o.diretor_email || o.email || '';
    return { id:id, nome:String(nome).trim(), email:String(mail).toLowerCase().trim(),
             grupo:grupo, detalhe:det.join(' · ') };
  }

  /* ---------- fotos ----------
     O portal já tem um endpoint /fotos que devolve { fotos:{id:url}, por_email:{email:url} },
     e as telas guardam isso em sessionStorage('fotos_map'). Aqui a gente REUSA esse cache:
     na maioria das telas ele já está quente e a lista sai com foto na hora. Só busca quando
     não existe (por exemplo se o Suporte for aberto logo após o login).
     Docente não tem e-mail no cadastro, então para ele a chave que funciona é o id. */
  var FOTOS = { fotos:{}, por_email:{} };
  function carregarFotos(){
    try{
      var c = sessionStorage.getItem('fotos_map');
      if(c){ var j = JSON.parse(c); FOTOS = { fotos:j.fotos||{}, por_email:j.por_email||{} }; return Promise.resolve(); }
    }catch(e){}
    return post('/fotos', {}).then(function(r){
      var d = Array.isArray(r) ? (r[0]||{}) : (r||{});
      FOTOS = { fotos:d.fotos||{}, por_email:d.por_email||{} };
      try{ sessionStorage.setItem('fotos_map', JSON.stringify({ fotos:FOTOS.fotos, por_email:FOTOS.por_email })); }catch(e){}
    }).catch(function(){ /* silencioso: sem foto a lista mostra as iniciais */ });
  }
  /* catalogo de materias: vem de graca no listar-docentes (filtros_disponiveis),
     entao nao precisa de endpoint novo. E o MESMO catalogo que o formulario de
     docentes usa no filtro, entao os nomes batem com o cadastro.
     Escopo: o que a pessoa enxerga. Para quem ve tudo (admin) vem completo;
     para uma supervisora, so as materias dos docentes dela — que e justamente
     o universo em que ela notaria alguem faltando. */
  var MATERIAS = null;   /* null = ainda nao buscado; [] = buscado e vazio */
  function carregarMaterias(){
    if(MATERIAS) return Promise.resolve(MATERIAS);
    return post(LISTAS[0].rota, LISTAS[0].corpo).then(function(r){
      var d = Array.isArray(r) ? (r[0]||{}) : (r||{});
      var fd = d.filtros_disponiveis || {};
      MATERIAS = (fd.disciplinas || []).filter(function(x){ return x && x.nome; })
        .sort(function(a,b){ return String(a.nome).localeCompare(String(b.nome),'pt-BR'); });
      return MATERIAS;
    }).catch(function(){ MATERIAS = []; return MATERIAS; });
  }

  function fotoDe(p){
    return (p.id && FOTOS.fotos[p.id]) || (p.email && FOTOS.por_email[p.email]) || '';
  }
  function iniciais(nome){
    var ps = String(nome||'').trim().split(/\s+/).filter(function(x){ return x.length > 2; });
    if(!ps.length) return '?';
    return ((ps[0][0] || '') + (ps.length > 1 ? (ps[ps.length-1][0] || '') : '')).toUpperCase();
  }

  /* ---------- casca do modal ---------- */
  function estilos(){
    if(document.getElementById('sup-estilos')) return;
    var st = document.createElement('style'); st.id = 'sup-estilos';
    st.textContent = ''
      /* fundo: escurece e desfoca o portal atras, com entrada suave */
      + '@keyframes supEntra{from{opacity:0}to{opacity:1}}'
      + '@keyframes supSobe{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}'
      + '.sup-bg{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;'
      + 'padding:20px;background:rgba(18,11,48,.62);backdrop-filter:blur(3px);animation:supEntra .18s ease}'

      + '.sup-cx{position:relative;width:min(700px,100%);max-height:92vh;display:flex;flex-direction:column;'
      + 'background:#fff;color:#241a4d;border-radius:22px;overflow:hidden;'
      + 'box-shadow:0 30px 80px rgba(18,11,48,.45);animation:supSobe .26s cubic-bezier(.2,.8,.3,1);'
      + "font-family:Inter,system-ui,-apple-system,'Segoe UI',sans-serif}"

      /* cabecalho em degrade, com a mandala como marca d'agua */
      + '.sup-hd{position:relative;padding:22px 24px;color:#fff;overflow:hidden;'
      + 'background:linear-gradient(135deg,#5b3fd6 0%,#8a6aff 48%,#d65aa0 100%)}'
      + '.sup-hd::after{content:"";position:absolute;right:-26px;top:-34px;width:150px;height:150px;opacity:.16;'
      + 'background:#fff;-webkit-mask:var(--mandala) center/contain no-repeat;mask:var(--mandala) center/contain no-repeat}'
      + '.sup-eyebrow{display:block;font-size:.66rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase;'
      + 'opacity:.82;margin-bottom:5px}'
      + '.sup-hd h3{margin:0;font-size:1.22rem;font-weight:850;letter-spacing:-.01em;position:relative;z-index:1}'
      + '.sup-x{position:absolute;top:16px;right:16px;z-index:2;width:34px;height:34px;border:0;border-radius:11px;'
      + 'cursor:pointer;background:rgba(255,255,255,.18);color:#fff;font-size:1.15rem;line-height:1;'
      + 'display:grid;place-items:center;transition:background .15s}'
      + '.sup-x:hover{background:rgba(255,255,255,.32)}'

      + '.sup-bd{padding:22px 24px;overflow:auto}'
      + '.sup-sub{margin:0 0 16px;font-size:.88rem;color:#6b648f;line-height:1.55}'

      /* cartao de opcao: icone redondo + titulo + descricao + seta */
      + '.sup-op{display:flex;align-items:flex-start;gap:13px;width:100%;text-align:left;padding:15px 16px;'
      + 'margin-bottom:11px;border-radius:15px;border:1.5px solid #ece8fa;background:#fff;cursor:pointer;'
      + 'transition:border-color .16s,box-shadow .16s,transform .16s}'
      + '.sup-op:hover{border-color:#8a6aff;box-shadow:0 8px 22px rgba(138,106,255,.16);transform:translateY(-1px)}'
      + '.sup-op:focus-visible{outline:2px solid #8a6aff;outline-offset:2px}'
      + '.sup-op i{flex:none;width:38px;height:38px;border-radius:11px;display:grid;place-items:center;'
      + 'background:linear-gradient(135deg,#f0ebff,#fbe9f3);color:#7b55f0}'
      + '.sup-op b{display:block;font-size:.94rem;font-weight:800;color:#241a4d;line-height:1.3}'
      + '.sup-op small{display:block;font-weight:500;color:#6b648f;margin-top:4px;font-size:.81rem;line-height:1.45}'
      + '.sup-op u{flex:none;margin-left:auto;align-self:center;color:#b6aee0;text-decoration:none;font-size:1.1rem}'

      + '.sup-busca{width:100%;padding:11px 14px;border:1.5px solid #ece8fa;border-radius:12px;margin-bottom:12px;'
      + 'font-size:.88rem;font-family:inherit;color:#241a4d}'
      + '.sup-busca:focus{outline:0;border-color:#8a6aff}'
      + '.sup-lista{max-height:min(52vh,460px);overflow:auto;border:1.5px solid #ece8fa;border-radius:14px;padding:0 0 6px;background:#fcfbff}'
      + '.sup-g{position:sticky;top:0;z-index:2;background:#fcfbff;font-size:.67rem;font-weight:850;letter-spacing:.1em;'
      + 'text-transform:uppercase;color:#9a92c4;padding:11px 14px 7px;box-shadow:0 1px 0 #efebfa}'
      + '.sup-li{display:flex;gap:11px;align-items:center;margin:2px 6px;padding:9px 10px;border-radius:10px;cursor:pointer;'
      + 'transition:background .12s}'
      + '.sup-li:hover{background:#f3efff}'
      + '.sup-li input{margin-top:3px;flex:none;accent-color:#8a6aff;width:16px;height:16px}'
      + '.sup-li .sup-nm{font-size:.88rem;line-height:1.4;font-weight:600;color:#33295e}'
      /* avatar: foto quando existe, iniciais quando não */
      + '.sup-av{flex:none;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;'
      + 'background:linear-gradient(135deg,#ece6ff,#fbe6f1);background-size:cover;background-position:center;'
      + 'color:#7b55f0;font-size:.7rem;font-weight:850;letter-spacing:.02em;overflow:hidden}'
      + '.sup-li small{display:block;color:#7d75a6;font-size:.77rem;font-weight:500;margin-top:1px}'

      + '.sup-campo{margin-bottom:14px}'
      + '.sup-campo label{display:block;font-size:.75rem;font-weight:800;letter-spacing:.03em;color:#5a5188;margin-bottom:6px}'
      + '.sup-campo input,.sup-campo select,.sup-campo textarea{width:100%;padding:11px 13px;border:1.5px solid #ece8fa;'
      + 'border-radius:12px;font-size:.89rem;font-family:inherit;color:#241a4d;background:#fff;transition:border-color .15s}'
      + '.sup-campo input:focus,.sup-campo select:focus,.sup-campo textarea:focus{outline:0;border-color:#8a6aff}'
      + '.sup-campo textarea{resize:vertical}'

      + '.sup-ft{display:flex;gap:10px;justify-content:flex-end;padding:16px 24px;border-top:1px solid #f0edfa;background:#fdfcff}'
      + '.sup-b{padding:11px 20px;border-radius:12px;border:1.5px solid #e6e1f7;background:#fff;cursor:pointer;'
      + 'font-size:.88rem;font-weight:800;color:#5a5188;font-family:inherit;transition:background .15s,border-color .15s}'
      + '.sup-b:hover{background:#f7f5ff;border-color:#cfc5f2}'
      + '.sup-b.pri{background:linear-gradient(135deg,#8a6aff,#d65aa0);border-color:transparent;color:#fff;'
      + 'box-shadow:0 8px 20px rgba(138,106,255,.32)}'
      + '.sup-b.pri:hover{filter:brightness(1.06)}'
      + '.sup-b[disabled]{opacity:.55;cursor:default;filter:none}'

      + '.sup-msg{display:flex;gap:9px;align-items:flex-start;padding:13px 15px;border-radius:13px;'
      + 'font-size:.86rem;font-weight:650;line-height:1.45;margin-bottom:15px}'
      + '.sup-msg.erro{background:#fdecf1;color:#9c1f45;border:1px solid #f7cfdc}'
      + '.sup-msg.ok{background:#e9f8f1;color:#0b6b48;border:1px solid #c6ecdb}'

      /* botao flutuante (canto inferior direito) */
      + '#sup-fab{position:fixed;right:22px;bottom:22px;z-index:9990;display:inline-flex;align-items:center;'
      + 'gap:0;overflow:hidden;height:52px;width:52px;padding:0 15px;border:0;border-radius:999px;cursor:pointer;'
      + 'background:linear-gradient(135deg,#8a6aff,#d65aa0);color:#fff;'
      + 'box-shadow:0 10px 28px rgba(138,106,255,.45);transition:width .25s cubic-bezier(.4,0,.2,1),gap .25s,box-shadow .2s}'
      + '#sup-fab:hover,#sup-fab:focus-visible{width:148px;gap:9px;box-shadow:0 14px 34px rgba(138,106,255,.55)}'
      + '#sup-fab svg{flex:none}'
      + '#sup-fab span{white-space:nowrap;font-weight:800;font-size:.88rem;opacity:0;transition:opacity .18s ease}'
      + '#sup-fab:hover span,#sup-fab:focus-visible span{opacity:1}'
      + '@media print{#sup-fab{display:none}}'
      + '@media(max-width:860px){#sup-fab{right:14px;bottom:14px}.sup-cx{border-radius:18px}}';
    document.head.appendChild(st);
  }

  var bg = null, estado = {};

  function fechar(){ if(bg){ bg.remove(); bg = null; } estado = {}; }

  function abrir(){
    estilos(); fechar();
    bg = document.createElement('div');
    bg.className = 'sup-bg';
    bg.addEventListener('click', function(e){ if(e.target === bg) fechar(); });
    document.body.appendChild(bg);
    document.addEventListener('keydown', function esc(e){
      if(e.key === 'Escape'){ fechar(); document.removeEventListener('keydown', esc); }
    });
    etapa1();
  }

  /* eyebrow = a trilha de onde a pessoa esta ("Suporte", "Suporte · Lista errada").
     Sem isso, no 2o e 3o passo o titulo sozinho nao diz de onde veio. */
  function moldura(titulo, corpoHTML, rodapeHTML, eyebrow){
    bg.innerHTML = '<div class="sup-cx" role="dialog" aria-modal="true" aria-label="' + esc(titulo) + '">'
      + '<div class="sup-hd">'
      +   '<span class="sup-eyebrow">' + esc(eyebrow || 'Suporte') + '</span>'
      +   '<h3>' + esc(titulo) + '</h3>'
      +   '<button class="sup-x" type="button" aria-label="Fechar">&times;</button>'
      + '</div>'
      + '<div class="sup-bd">' + corpoHTML + '</div>'
      + (rodapeHTML ? '<div class="sup-ft">' + rodapeHTML + '</div>' : '')
      + '</div>';
    bg.querySelector('.sup-x').addEventListener('click', fechar);
  }
  /* cartao de opcao, com icone */
  function cartao(id, ico, titulo, descricao){
    return '<button class="sup-op" type="button" id="' + id + '">'
      + '<i>' + ico + '</i>'
      + '<span><b>' + esc(titulo) + '</b><small>' + esc(descricao) + '</small></span>'
      + '<u>&rsaquo;</u></button>';
  }
  var ICO_LISTA = '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
    + ' stroke-linecap="round"><path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/></svg>';
  var ICO_SOBRA = '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
    + ' stroke-linecap="round"><circle cx="9" cy="8" r="3.4"/><path d="M3 20c0-3.2 2.7-5.2 6-5.2s6 2 6 5.2"/>'
    + '<path d="M17 9l4 4M21 9l-4 4"/></svg>';
  var ICO_FALTA = '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
    + ' stroke-linecap="round"><circle cx="9" cy="8" r="3.4"/><path d="M3 20c0-3.2 2.7-5.2 6-5.2s6 2 6 5.2"/>'
    + '<path d="M19 9v6M16 12h6"/></svg>';
  var ICO_OUTRO = '<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"'
    + ' stroke-linecap="round"><path d="M21 12a9 9 0 1 1-4.2-7.6"/><path d="M8 11h6M8 15h4"/>'
    + '<path d="M18.5 3.5v5M21 6h-5"/></svg>';
  function q(sel){ return bg.querySelector(sel); }

  /* ---------- etapa 1: qual é o problema ---------- */
  function etapa1(){
    moldura('Como podemos ajudar?',
      '<p class="sup-sub">Escolha o que está acontecendo. O chamado vai direto para a equipe que cuida do portal.</p>'
      + cartao('sup-op-vis', ICO_LISTA, 'Lista de pessoas errada',
               'Você vê alguém que não é da sua equipe, ou falta alguém que deveria aparecer.')
      /* a opção aberta existe porque a lista fixa só cobre o que a gente já
         previu; sem ela, todo caso novo vira e-mail solto e não entra na fila */
      + cartao('sup-op-outro', ICO_OUTRO, 'Outro assunto',
               'Qualquer outra coisa: um erro na tela, uma dúvida ou um pedido.'),
      '<button class="sup-b" type="button" id="sup-fechar">Fechar</button>');
    q('#sup-op-vis').addEventListener('click', etapa2);
    q('#sup-op-outro').addEventListener('click', etapaOutro);
    q('#sup-fechar').addEventListener('click', fechar);
  }

  /* ---------- etapa 2b: assunto livre ----------
     Aqui não há lista para marcar: o chamado É o texto. Por isso o botão de
     enviar confere o campo antes de chamar o servidor — o `registrar` também
     recusa vazio, mas a recusa só chegaria depois de uma ida e volta. */
  function etapaOutro(){
    moldura('Outro assunto',
      '<p class="sup-sub">Escreva com as suas palavras o que aconteceu. Se for um erro, conte em que tela e o que você estava fazendo.</p>'
      + '<div class="sup-campo"><label>O que você quer relatar</label>'
      + '<textarea id="sup-obs" rows="6" placeholder="Ex.: na tela de avaliação da supervisão o botão de salvar não responde depois que eu escolho a data da devolutiva."></textarea></div>',
      '<button class="sup-b" type="button" id="sup-voltar">Voltar</button>'
      + '<button class="sup-b pri" type="button" id="sup-env">Enviar chamado</button>',
      'Suporte');
    q('#sup-voltar').addEventListener('click', etapa1);
    q('#sup-env').addEventListener('click', function(){
      var t = q('#sup-obs').value.trim();
      if(!t){ alerta('Escreva o que você quer relatar.'); return; }
      enviar({ tipo:'outro', subtipo:'outro', observacao:t });
    });
  }

  /* ---------- etapa 2: sobra ou falta ---------- */
  function etapa2(){
    moldura('Lista de pessoas errada',
      '<p class="sup-sub">Qual dos dois casos é o seu?</p>'
      + cartao('sup-sobra', ICO_SOBRA, 'Estou vendo alguém que não deveria',
               'Aparece na sua lista alguém que não é da sua equipe.')
      + cartao('sup-falta', ICO_FALTA, 'Não vejo alguém que deveria',
               'Falta alguém que é da sua equipe e não aparece para você.'),
      '<button class="sup-b" type="button" id="sup-voltar">Voltar</button>',
      'Suporte');
    q('#sup-sobra').addEventListener('click', etapaSobra);
    q('#sup-falta').addEventListener('click', etapaFalta);
    q('#sup-voltar').addEventListener('click', etapa1);
  }

  /* ---------- etapa 3a: marcar quem sobra ---------- */
  function etapaSobra(){
    moldura('Quem não deveria aparecer', '<p class="sup-sub">Carregando a sua lista...</p>',
      '<button class="sup-b" type="button" id="sup-voltar">Voltar</button>', 'Suporte · Lista de pessoas errada');
    q('#sup-voltar').addEventListener('click', etapa2);

    /* as fotos entram no MESMO Promise.all das listas, e não soltas em paralelo:
       soltas, elas poderiam chegar depois da lista já desenhada e a primeira
       renderização sairia só com iniciais, trocando para foto no meio do uso.
       Como o mapa quase sempre já está em cache, isso não custa espera. */
    Promise.all([carregarFotos()].concat(LISTAS.map(function(l){
      return post(l.rota, l.corpo).then(function(r){
        return extrairLista(r).map(function(o){ return normalizar(o, l.grupo); });
      }).catch(function(){ return []; });
    }))).then(function(tudo){
      var partes = tudo.slice(1);
      var todos = [], vistos = {};
      partes.forEach(function(p){ p.forEach(function(x){
        if(!x.nome) return;
        var k = (x.id || x.nome) + '|' + x.grupo;
        if(vistos[k]) return; vistos[k] = 1; todos.push(x);
      }); });
      if(!bg) return;
      if(!todos.length){ semLista(); return; }
      estado.todos = todos; estado.marcados = {};
      renderSobra('');
    });
  }

  function semLista(){
    moldura('Quem não deveria aparecer',
      '<div class="sup-msg erro">Não consegui carregar a sua lista agora.</div>'
      + '<p class="sup-sub">Você pode descrever o caso em texto que a gente identifica aqui.</p>'
      + '<div class="sup-campo"><label>O que está aparecendo indevidamente</label>'
      + '<textarea id="sup-obs" rows="4" placeholder="Ex.: aparece o professor Fulano, que é da unidade X"></textarea></div>',
      '<button class="sup-b" type="button" id="sup-voltar">Voltar</button>'
      + '<button class="sup-b pri" type="button" id="sup-env">Enviar</button>');
    q('#sup-voltar').addEventListener('click', etapa2);
    q('#sup-env').addEventListener('click', function(){
      var t = q('#sup-obs').value.trim();
      if(!t){ alerta('Escreva o que está aparecendo indevidamente.'); return; }
      enviar({ subtipo:'nao_vejo', pessoa:{ nome:'(descrito em texto)', cargo:'OUTRO' }, observacao:'VEJO INDEVIDO — ' + t });
    });
  }

  function renderSobra(busca){
    var filtro = String(busca||'').toLowerCase();
    var porGrupo = {};
    estado.todos.forEach(function(p){
      if(filtro && (p.nome + ' ' + p.detalhe).toLowerCase().indexOf(filtro) < 0) return;
      (porGrupo[p.grupo] = porGrupo[p.grupo] || []).push(p);
    });
    var html = '<p class="sup-sub">Marque quem <b>não</b> é da sua equipe. São as pessoas que o portal mostra para você avaliar.</p>'
      + '<input class="sup-busca" id="sup-busca" placeholder="Buscar pelo nome..." value="' + esc(busca||'') + '">'
      + '<div class="sup-lista">';
    var vazio = true;
    Object.keys(porGrupo).forEach(function(g){
      vazio = false;
      html += '<div class="sup-g">' + esc(g) + '</div>';
      porGrupo[g].forEach(function(p){
        var k = (p.id || p.nome) + '|' + p.grupo;
        var f = fotoDe(p);
        html += '<label class="sup-li"><input type="checkbox" data-k="' + esc(k) + '"'
          + (estado.marcados[k] ? ' checked' : '') + '>'
          + '<span class="sup-av"' + (f ? ' style="background-image:url(' + esc(f) + ')"' : '') + '>'
          + (f ? '' : esc(iniciais(p.nome))) + '</span>'
          + '<span class="sup-nm">' + esc(p.nome) + (p.detalhe ? '<small>' + esc(p.detalhe) + '</small>' : '') + '</span></label>';
      });
    });
    if(vazio) html += '<div class="sup-g">nenhum nome encontrado</div>';
    html += '</div>'
      + '<div class="sup-campo" style="margin-top:14px"><label>Observação (opcional)</label>'
      + '<textarea id="sup-obs" rows="2" placeholder="Algo que ajude a entender o caso">' + esc(estado.obs||'') + '</textarea></div>';

    moldura('Quem não deveria aparecer', html,
      '<button class="sup-b" type="button" id="sup-voltar">Voltar</button>'
      + '<button class="sup-b pri" type="button" id="sup-env">Enviar chamado</button>', 'Suporte · Lista de pessoas errada');

    q('#sup-busca').addEventListener('input', function(){
      estado.obs = q('#sup-obs').value;
      renderSobra(this.value);
      var b = q('#sup-busca'); b.focus(); b.setSelectionRange(b.value.length, b.value.length);
    });
    Array.prototype.forEach.call(bg.querySelectorAll('.sup-li input'), function(cb){
      cb.addEventListener('change', function(){
        if(this.checked) estado.marcados[this.dataset.k] = 1; else delete estado.marcados[this.dataset.k];
      });
    });
    q('#sup-voltar').addEventListener('click', etapa2);
    q('#sup-env').addEventListener('click', function(){
      var chaves = Object.keys(estado.marcados);
      if(!chaves.length){ alerta('Marque ao menos uma pessoa.'); return; }
      var itens = estado.todos.filter(function(p){ return estado.marcados[(p.id||p.nome)+'|'+p.grupo]; })
        .map(function(p){ return { id:p.id, nome:p.nome, grupo:p.grupo, detalhe:p.detalhe }; });
      enviar({ subtipo:'vejo_indevido', itens:itens, observacao:q('#sup-obs').value.trim() });
    });
  }

  /* ---------- etapa 3b: descrever quem falta ---------- */
  function etapaFalta(){
    var opts = CARGOS.map(function(c){ return '<option value="'+c.v+'">'+esc(c.t)+'</option>'; }).join('');
    moldura('Quem está faltando',
      '<p class="sup-sub">Diga quem deveria aparecer para você. Quanto mais específico, mais rápido a gente acha no cadastro.</p>'
      + '<div class="sup-campo"><label>Nome completo</label><input id="sup-nome" placeholder="Nome da pessoa"></div>'
      + '<div class="sup-campo"><label>Cargo</label><select id="sup-cargo">' + opts + '</select></div>'
      + '<div id="sup-cond"></div>'
      + '<div class="sup-campo"><label>Observação (opcional)</label>'
      + '<textarea id="sup-obs" rows="2" placeholder="Unidade, turma, qualquer detalhe que ajude"></textarea></div>',
      '<button class="sup-b" type="button" id="sup-voltar">Voltar</button>'
      + '<button class="sup-b pri" type="button" id="sup-env">Enviar chamado</button>', 'Suporte · Lista de pessoas errada');

    function condicionais(){
      var c = q('#sup-cargo').value, h = '';
      if(c === 'DOCENTE'){
        h = '<div class="sup-campo"><label>Ano / série</label><input id="sup-ano" placeholder="Ex.: 7º ano"></div>'
          + '<div class="sup-campo"><label>Matéria</label>'
          +   '<select id="sup-materia"><option value="">Carregando...</option></select>'
          +   '<input id="sup-materia-txt" class="hidden-x" style="display:none;margin-top:8px" placeholder="Qual materia?">'
          + '</div>';
      } else if(c === 'SUPERVISAO_SEGMENTO' || c === 'DIRECAO_PEDAGOGICA'){
        h = '<div class="sup-campo"><label>Segmento</label><select id="sup-seg">'
          + SEGMENTOS.map(function(s){ return '<option>'+s+'</option>'; }).join('') + '</select></div>';
      } else if(c === 'COORDENACAO_AREA'){
        h = '<div class="sup-campo"><label>Área</label><input id="sup-area" placeholder="Ex.: Linguagens"></div>';
      } else if(c === 'DIRECAO_UNIDADE'){
        h = '<div class="sup-campo"><label>Unidade</label><input id="sup-unidade" placeholder="Ex.: Barra Olímpica"></div>';
      }
      q('#sup-cond').innerHTML = h;
    }
    function popularMaterias(){
      var sel = q('#sup-materia'); if(!sel) return;
      carregarMaterias().then(function(ms){
        var sel2 = q('#sup-materia'); if(!sel2) return;   /* a pessoa pode ter trocado de cargo no meio */
        if(!ms.length){
          /* catalogo vazio: volta para texto livre em vez de deixar uma lista morta */
          var txt = q('#sup-materia-txt');
          sel2.style.display = 'none';
          if(txt){ txt.style.display = ''; txt.placeholder = 'Ex.: Matemática'; }
          return;
        }
        sel2.innerHTML = '<option value=>Selecione...</option>'
          + ms.map(function(m){ return '<option>' + esc(m.nome) + '</option>'; }).join('')
          + '<option value=__outra>Outra (não está na lista)</option>';
        sel2.addEventListener('change', function(){
          var txt = q('#sup-materia-txt'); if(!txt) return;
          txt.style.display = (this.value === '__outra') ? '' : 'none';
        });
      });
    }
    q('#sup-cargo').addEventListener('change', function(){ condicionais(); popularMaterias(); });
    condicionais(); popularMaterias();

    q('#sup-voltar').addEventListener('click', etapa2);
    q('#sup-env').addEventListener('click', function(){
      var nome = q('#sup-nome').value.trim();
      if(!nome){ alerta('Informe o nome da pessoa que está faltando.'); return; }
      var cargo = q('#sup-cargo').value;
      var p = { nome:nome, cargo:cargo };
      var det = [];
      if(q('#sup-ano'))     { p.ano = q('#sup-ano').value.trim();         if(p.ano) det.push(p.ano); }
      if(q('#sup-materia')) {
        var mv = q('#sup-materia').value.trim();
        if(mv === '__outra' || !mv){ var mt = q('#sup-materia-txt'); mv = mt ? mt.value.trim() : ''; }
        p.materia = mv; if(mv) det.push(mv);
      }
      if(q('#sup-seg'))     { p.segmento = q('#sup-seg').value;           det.push(p.segmento); }
      if(q('#sup-area'))    { p.area = q('#sup-area').value.trim();       if(p.area) det.push(p.area); }
      if(q('#sup-unidade')) { p.unidade = q('#sup-unidade').value.trim(); if(p.unidade) det.push(p.unidade); }
      p.detalhe = det.join(' · ');
      enviar({ subtipo:'nao_vejo', pessoa:p, observacao:q('#sup-obs').value.trim() });
    });
  }

  function alerta(txt){
    var bd = bg && bg.querySelector('.sup-bd'); if(!bd) return;
    var m = bd.querySelector('.sup-msg.erro');
    if(!m){ m = document.createElement('div'); m.className = 'sup-msg erro'; bd.insertBefore(m, bd.firstChild); }
    m.textContent = txt;
  }

  function enviar(dados){
    var btn = q('#sup-env'); if(btn){ btn.disabled = true; btn.textContent = 'Enviando...'; }
    post('/suporte/registrar', Object.assign({
      tipo:'visualizacao_pessoas',
      tela_origem:(location.pathname || '').replace(/^\//,'') || 'index'
    }, dados)).then(function(r){
      var res = Array.isArray(r) ? (r[0] || {}) : (r || {});
      if(!bg) return;
      if(res.registrado === true){
        moldura('Chamado enviado',
          '<div class="sup-msg ok">Recebido. A equipe do portal vai olhar o seu caso.</div>'
          + '<p class="sup-sub">Você pode continuar usando o portal normalmente.</p>',
          '<button class="sup-b pri" type="button" id="sup-ok">Fechar</button>');
        q('#sup-ok').addEventListener('click', fechar);
      } else {
        if(btn){ btn.disabled = false; btn.textContent = 'Enviar chamado'; }
        alerta(res.mensagem || 'Não consegui registrar o chamado agora. Tente de novo em instantes.');
      }
    }).catch(function(){
      if(btn){ btn.disabled = false; btn.textContent = 'Enviar chamado'; }
      alerta('Falha de comunicação. Tente de novo em instantes.');
    });
  }

  /* ---------- botão flutuante ----------
     Vai DENTRO do #app quando ele existe, pelo mesmo motivo do menu lateral:
     no index.html o #app é escondido nas telas de login, e um botão de suporte
     boiando sobre a tela de quem ainda não entrou não faz sentido (nem teria
     sessão para abrir chamado). Nas telas sem #app, vai no body. */
  var ICONE = '<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor"'
    + ' stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/>'
    + '<circle cx="12" cy="12" r="3.6"/>'
    + '<path d="M5.6 5.6l3.9 3.9M14.5 14.5l3.9 3.9M18.4 5.6l-3.9 3.9M9.5 14.5l-3.9 3.9"/></svg>';

  function botaoFlutuante(){
    if(document.getElementById('sup-fab')) return;
    estilos();
    var b = document.createElement('button');
    b.id = 'sup-fab';
    b.type = 'button';
    b.title = 'Suporte — relatar um problema';
    b.setAttribute('aria-label', 'Suporte');
    b.innerHTML = ICONE + '<span>Suporte</span>';
    b.addEventListener('click', abrir);
    (document.getElementById('app') || document.body).appendChild(b);
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', botaoFlutuante);
  else botaoFlutuante();

  window.abrirSuporte = abrir;
})();
